-- Exclusive: I intend to modify this balance.
BEGIN;
SELECT balance FROM accounts WHERE id = 1 FOR UPDATE;
-- application checks balance >= amount, then:
UPDATE accounts SET balance = balance - 100 WHERE id = 1;
COMMIT;

-- Shared: I need it stable while I read, but will not modify it.
BEGIN;
SELECT balance FROM accounts WHERE id = 1 FOR SHARE;
-- other writers with FOR UPDATE now block; other FOR SHARE readers proceed.
COMMIT;

-- Non-blocking variants for latency-sensitive paths:
-- Fail fast instead of queuing:
SELECT balance FROM accounts WHERE id = 1 FOR UPDATE NOWAIT;
-- Skip contested rows (job queues):
SELECT id FROM jobs WHERE status = 'pending' ORDER BY id LIMIT 1 FOR UPDATE SKIP LOCKED;
